pub(crate) fn decode_semio_snapshot_binary(bytes: &[u8]) -> Result<SemioSnapshot, String> {
    let mut reader = store::ByteReader::new(bytes);
    let format = reader.read_u8().map_err(|e| e.to_string())?;
    if format != PACK_BINARY_FORMAT {
